def solve(I):
    H,W=len(I),len(I[0])
    counts=defaultdict(int)
    for r in range(H):
        for c in range(W): counts[I[r][c]]+=1
    bg=max(counts,key=counts.get)
    d=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg: d[I[r][c]].append((r,c))
    rects=[]; strays=[]
    for col,ps in d.items():
        rs=[p[0] for p in ps]; cs=[p[1] for p in ps]
