        if len(ps)==4 and set(ps)=={(min(rs),min(cs)),(min(rs),max(cs)),(max(rs),min(cs)),(max(rs),max(cs))} and hh>=2 and ww>=2:
            rects.append((col,min(rs),min(cs),hh,ww))
        else: strays.append((col,ps))
    fr=max(rects,key=lambda r:r[3]*r[4])
    fcol,fir,fic,fh,fw=fr
    # canonical origin: top-left of the frame rect
    # group cells rel to frame origin
    def rel(ps): return [(r-fir,c-fic) for r,c in ps]
    cells={}
    for col,ps in [(fr,[p for p in d[fr]])]+strays:
        cells[col]=rel(ps)
    R,C=fh,fw
    out=[[bg]*C for _ in range(R)]
    # shifts: minimize |sr|+|sc| subject to (cell+shift) in [0,R)x[0,C) for all cells
    def best(cells):
        res=None
        for sr in range(-R*2,R*2+1):
            for sc in range(-C*2,C*2+1):
                good=all(0<=r+sr<R and 0<=c+sc<C for r,c in cells)
                if good:
                    key=abs(sr)+abs(sc)
                    if res is None or key<res[0]: res=(key,sr,sc)
        return res[1:]
    shifts={fcol:(0,0)}
    for col,ps in cells:
        if col==fcol: continue
        tr,t_=best(ps); shifts[col]=(tr,t_)
    for col,ps in sorted(cells.items(),key=lambda kv:kv[0]):
        sr,sc=shifts[col]
        for r,c in ps:
            rr,cc=r+sr,c+sc
            out[rr][cc]=col
    # frame drawn last so its corners win conflicts
    out[0][0]=fcol; out[0][C-1]=fcol; out[R-1][0]=fcol; out[R-1][C-1]=fcol
    return out
