# For each demo, recover true shifts by matching out stray colors against input stray cells.
def info(I,O):
    cnt=collections.Counter(x for row in I for x in row); bg=cnt.most_common(1)[0][0]
    ic_=collections.defaultdict(list)
    for r,row in enumerate(I):
        for c,x in enumerate(row):
            if x!=bg: ic_[x].append((r,c))
    fc=None
    for c,v in ic_.items():
        if len(v)==4:
            rs=[r for r,_ in v]; cs=[c for _,c in v]
            if {(min(rs),min(cs)),(min(rs),max(cs)),(max(rs),min(cs)),(max(rs),max(cs))}==set(v):
                fc=c; break
    fr0=min(r for r,_ in ic_[fc]); f1=max(r for r,_ in ic_[fc]); f0=min(c for _,c in ic_[fc]); f1c=max(c for _,c in ic_[fc])
    R,C=f1-fr0+1,f1c-f0+1
    # out: remove frame-color cells & bg; group remaining by color into components (4-conn)
    occ={(r,c) for r in range(R) for c in range(C) if O[r][c]!=bg and O[r][c]!=fc}
    used=set(); true={}
    seen=[[False]*C for _ in range(R)]
    comps=[]
    for r_ in range(R):
        for c_ in range(C):
            if occ[(r_,c_)] and not seen[r_][c_]:
                st=[(r_,c_)]; comp=[]
                seen[r_][c_]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=a+da,b+db
                        if 0<=rr<R and 0<=cc<C and occ[(rr,cc)] and not seen[rr][cc]:
                            seen[rr][cc]=True; st.append((rr,cc))
                comps.append(comp)
    outcells=collections.defaultdict(set)
    for comp in comps:
        col=O[comp[0][0]][comp[0][1]]
        for p in comp: outcells[col].add(p)
    res={}
    for col,ps in outcells.items():
        inp=[(r-fr0,c-f0) for r,c in ic_[col]]
        found=None
        for dr in range(-R,R+1):
            for dc in range(-C,C+1):
                pts={(a+dr,b+dc) for a,b in inp}
                if pts==ps: found=(dr,dc)
        res[col]=(inp,found)
    return res,(R,C),fc
