                    if not all(I[r0][c0+b]==col_ or I[r0+R-1][c0+b]==col_ for b in range(C)): continue
                    inner=[(r,c) for r in range(r0+1,r0+R-1) for c in range(c0+1,c0+C-1)]
                    if any(I[r][c]==col_ for r,c in inner): continue
                    stray_ok=all(not(r0<=r<r0+R and c0<=c<c0+C) or I[r][c]==col_ for r in range(H) for c in range(W) if I[r][c]!=bg)
